#!/usr/bin/env bash
# Checks the licence header of each Rust source file (plan section 11, duty 3).
# Usage: check-headers.sh [file...]; with no argument it checks every .rs file below
# rust/crates/*/src and each port.rs below rust/recorded (the other files there are
# generated by rust-anything), except the placeholder crate ria-workspace.
# Line 1 is either `// Ported from ardia <path> at <commit>.` (then lines 2 and 3 are the
# fixed notice) or `// Ria original, no Ardia source.` A file with no bytes passes.
set -euo pipefail

root=$(cd "$(dirname "$0")/.." && pwd)
commit=551d3c13c

if [ $# -eq 0 ]; then
  files=()
  while IFS= read -r f; do files+=("$f"); done < <(
    { find "$root/crates" -name '*.rs' -path '*/src/*' -not -path '*/ria-workspace/*'
      find "$root/recorded" -name port.rs -path '*/src/*'; } | sort)
else
  files=("$@")
fi

bad=0
for f in "${files[@]}"; do
  [ -s "$f" ] || continue
  l1=$(sed -n 1p "$f"); l2=$(sed -n 2p "$f"); l3=$(sed -n 3p "$f")
  if [[ "$l1" == "// Ria original, no Ardia source." ]]; then
    continue
  elif [[ "$l1" =~ ^//\ Ported\ from\ ardia\ [^\ ]+\ at\ ${commit}\.$ \
    && "$l2" == "// Copyright 2026 Mantra Patel, Apache-2.0." \
    && "$l3" == "// This file is a Rust port of that file, with changes." ]]; then
    continue
  fi
  echo "bad header: $f" >&2
  bad=1
done
[ "$bad" -eq 0 ] && echo "headers ok: ${#files[@]} files"
exit "$bad"
